<div class="page-header"><div><p class="eyebrow">PEOPLE &amp; PROFILES</p><h1>Students</h1><p>Student records from the institutional database.</p></div><?php if(AuthMiddleware::user()['role_slug']==='administrator'):?><a href="/students/new" class="btn btn-primary">+ Register student</a><?php endif; ?></div>
<section class="panel"><form method="get" action="/students" class="search-row"><input class="form-control" type="search" name="q" maxlength="120" value="<?= e($search) ?>" placeholder="Search name or matric number"><button class="btn btn-primary" type="submit">Search</button></form>
<div class="table-scroll"><table class="table table-clean"><thead><tr><th>Matric number</th><th>Full name</th><th>Email</th><th>Programme</th><th>Level</th><th>Status</th><?php if(AuthMiddleware::user()['role_slug']==='administrator'):?><th>Manage</th><?php endif; ?></tr></thead><tbody><?php foreach($items as $r):?><tr><td><strong><?= e($r['matriculation_number']) ?></strong></td><td><?= e($r['first_name'].' '.$r['last_name']) ?></td><td><?= e($r['email']) ?></td><td><?= e($r['programme_name']??'—') ?></td><td><?= e($r['level_name']??'—') ?></td><td><span class="status-pill <?= $r['account_status']==='active'?'active':'inactive' ?>"><?= e($r['account_status']) ?></span></td><?php if(AuthMiddleware::user()['role_slug']==='administrator'):?><td><div class="inline-actions"><a class="btn btn-outline-primary btn-sm" href="/students/edit?id=<?= (int)$r['id'] ?>">Edit</a><form method="post" action="/students/status"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="status" value="<?= $r['account_status']==='active'?'suspended':'active' ?>"><button class="btn btn-outline-secondary btn-sm"><?= $r['account_status']==='active'?'Deactivate':'Reactivate' ?></button></form></div></td><?php endif; ?></tr><?php endforeach; ?></tbody></table><?php if(!$items):?><p class="empty-state">No students match your search.</p><?php endif; ?></div><?= page_links($page,$total,'/students?q='.rawurlencode($search)) ?></section>
